import React, { useState, useRef } from 'react';
import { useSettings } from '../contexts/SettingsContext';

interface SettingsSectionProps {
  title: string;
  children: React.ReactNode;
  isOpen: boolean;
  onToggle: () => void;
}

const SettingsSection: React.FC<SettingsSectionProps> = ({ title, children, isOpen, onToggle }) => (
  <div className="bg-white rounded-lg shadow-sm border border-secondary-200 transform transition-all duration-300 hover:shadow-md hover:scale-[1.01]">
    <button
      onClick={onToggle}
      className="w-full px-6 py-4 text-left flex items-center justify-between hover:bg-secondary-50 transition-all duration-300 rounded-t-lg group"
    >
      <h3 className="text-lg font-semibold text-secondary-900 transition-colors duration-200 group-hover:text-primary-600">{title}</h3>
      <svg
        className={`w-5 h-5 text-secondary-400 transition-all duration-300 group-hover:text-primary-500 ${isOpen ? 'rotate-180 scale-110' : 'hover:scale-110'}`}
        fill="none"
        stroke="currentColor"
        viewBox="0 0 24 24"
      >
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
      </svg>
    </button>
    <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isOpen ? 'max-h-[2000px] opacity-100' : 'max-h-0 opacity-0'}`}>
      <div className="px-6 pb-6 border-t border-secondary-100 animate-fadeIn">
        {children}
      </div>
    </div>
  </div>
);

interface InputFieldProps {
  label: string;
  value: string | number;
  onChange: (value: string | number) => void;
  type?: 'text' | 'number' | 'url';
  placeholder?: string;
  min?: number;
  max?: number;
}

const InputField: React.FC<InputFieldProps> = ({ label, value, onChange, type = 'text', placeholder, min, max }) => (
  <div className="mb-4 transform transition-all duration-300 hover:translate-x-1">
    <label className="block text-sm font-medium text-secondary-700 mb-2 transition-colors duration-200">{label}</label>
    <input
      type={type}
      value={value}
      onChange={(e) => onChange(type === 'number' ? Number(e.target.value) : e.target.value)}
      placeholder={placeholder}
      min={min}
      max={max}
      className="w-full px-3 py-2 border border-secondary-300 rounded-md focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-300 hover:border-primary-300 hover:shadow-sm focus:scale-[1.02]"
    />
  </div>
);

interface SelectFieldProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  options: { value: string; label: string }[];
}

const SelectField: React.FC<SelectFieldProps> = ({ label, value, onChange, options }) => (
  <div className="mb-4 transform transition-all duration-300 hover:translate-x-1">
    <label className="block text-sm font-medium text-secondary-700 mb-2 transition-colors duration-200">{label}</label>
    <select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      className="w-full px-3 py-2 border border-secondary-300 rounded-md focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-300 hover:border-primary-300 hover:shadow-sm focus:scale-[1.02] cursor-pointer"
    >
      {options.map(option => (
        <option key={option.value} value={option.value}>{option.label}</option>
      ))}
    </select>
  </div>
);

interface ToggleFieldProps {
  label: string;
  description?: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

const ToggleField: React.FC<ToggleFieldProps> = ({ label, description, checked, onChange }) => (
  <div className="flex items-start justify-between mb-4 group transform transition-all duration-300 hover:translate-x-1">
    <div className="flex-1">
      <label className="block text-sm font-medium text-secondary-700 transition-colors duration-200 group-hover:text-primary-600 cursor-pointer">{label}</label>
      {description && <p className="text-xs text-secondary-500 mt-1 transition-colors duration-200 group-hover:text-secondary-600">{description}</p>}
    </div>
    <button
      onClick={() => onChange(!checked)}
      className={`relative inline-flex h-6 w-11 items-center rounded-full transition-all duration-300 transform hover:scale-110 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 ${
        checked ? 'bg-primary-600 shadow-lg' : 'bg-secondary-200 hover:bg-secondary-300'
      }`}
    >
      <span
        className={`inline-block h-4 w-4 transform rounded-full bg-white transition-all duration-300 shadow-lg ${
          checked ? 'translate-x-6 scale-110' : 'translate-x-1'
        }`}
      />
    </button>
  </div>
);

export const Settings: React.FC = () => {
  const { settings, updateSettings, resetSettings, exportSettings, importSettings } = useSettings();
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({
    connection: true,
    ui: false,
    monitoring: false,
    security: false,
    export: false,
  });
  const [notification, setNotification] = useState<string>('');
  const [notificationType, setNotificationType] = useState<'success' | 'error'>('success');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const toggleSection = (section: string) => {
    setOpenSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification(message);
    setNotificationType(type);
    setTimeout(() => setNotification(''), 3000);
  };

  const handleExport = () => {
    const settingsData = exportSettings();
    const blob = new Blob([settingsData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'tetracore-settings.json';
    a.click();
    URL.revokeObjectURL(url);
    showNotification('Налаштування експортовано успішно!', 'success');
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        if (importSettings(content)) {
          showNotification('Налаштування імпортовано успішно!', 'success');
        } else {
          showNotification('Помилка при імпорті налаштувань!', 'error');
        }
      };
      reader.readAsText(file);
    }
  };

  const handleReset = (category?: keyof typeof settings) => {
    if (window.confirm('Ви впевнені, що хочете скинути налаштування?')) {
      resetSettings(category);
      showNotification(category ? `Розділ "${category}" скинуто!` : 'Всі налаштування скинуто!', 'success');
    }
  };

  return (
    <div className="max-w-4xl mx-auto animate-fadeIn">
      {/* Header */}
      <div className="mb-8 transform transition-all duration-700 animate-slideInFromTop">
        <h1 className="text-3xl font-bold text-secondary-900 mb-2 bg-gradient-to-r from-primary-600 to-secondary-800 bg-clip-text text-transparent">
          Налаштування
        </h1>
        <p className="text-secondary-600 animate-pulse">Конфігурація TetraCore StreamHub</p>
      </div>

      {/* Notification */}
      {notification && (
        <div className={`mb-6 p-4 rounded-lg border animate-bounceIn transition-all duration-500 ${
          notificationType === 'success' 
            ? 'bg-green-100 border-green-400 text-green-700' 
            : 'bg-red-100 border-red-400 text-red-700'
        }`}>
          <div className="flex items-center">
            <div className={`w-2 h-2 rounded-full mr-3 animate-pulse ${
              notificationType === 'success' ? 'bg-green-500' : 'bg-red-500'
            }`}></div>
            {notification}
          </div>
        </div>
      )}

      {/* Import/Export Controls */}
      <div className="mb-8 bg-white rounded-lg shadow-sm border border-secondary-200 p-6 transform transition-all duration-500 hover:shadow-lg hover:scale-[1.01] animate-slideInFromLeft">
        <h3 className="text-lg font-semibold text-secondary-900 mb-4 flex items-center">
          <div className="w-2 h-2 bg-primary-500 rounded-full mr-3 animate-pulse"></div>
          Управління налаштуваннями
        </h3>
        <div className="flex flex-wrap gap-4">
          <button
            onClick={handleExport}
            className="px-4 py-2 bg-primary-600 text-white rounded-md hover:bg-primary-700 transition-all duration-300 transform hover:scale-105 hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 active:scale-95"
          >
            <span className="flex items-center">
              <svg className="w-4 h-4 mr-2 animate-bounce" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              Експортувати налаштування
            </span>
          </button>
          <button
            onClick={() => fileInputRef.current?.click()}
            className="px-4 py-2 bg-secondary-600 text-white rounded-md hover:bg-secondary-700 transition-all duration-300 transform hover:scale-105 hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-secondary-500 focus:ring-offset-2 active:scale-95"
          >
            <span className="flex items-center">
              <svg className="w-4 h-4 mr-2 animate-bounce" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
              </svg>
              Імпортувати налаштування
            </span>
          </button>
          <button
            onClick={() => handleReset()}
            className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-all duration-300 transform hover:scale-105 hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 active:scale-95"
          >
            <span className="flex items-center">
              <svg className="w-4 h-4 mr-2 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
              Скинути всі налаштування
            </span>
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".json"
            onChange={handleImport}
            className="hidden"
          />
        </div>
      </div>

      {/* Settings Sections */}
      <div className="space-y-6">
        {/* Connection Settings */}
        <div className="animate-slideInFromRight" style={{animationDelay: '0.1s'}}>
          <SettingsSection
            title="🔗 Налаштування підключення"
            isOpen={openSections.connection}
            onToggle={() => toggleSection('connection')}
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
              <InputField
                label="WebSocket URL"
                value={settings.connection.websocketUrl}
                onChange={(value) => updateSettings('connection', { websocketUrl: value })}
                type="url"
                placeholder="ws://localhost"
              />
              <InputField
                label="WebSocket Port"
                value={settings.connection.websocketPort}
                onChange={(value) => updateSettings('connection', { websocketPort: value })}
                type="number"
                min={1}
                max={65535}
              />
              <InputField
                label="API Endpoint"
                value={settings.connection.apiEndpoint}
                onChange={(value) => updateSettings('connection', { apiEndpoint: value })}
                type="url"
                placeholder="http://localhost:8000/api"
              />
              <InputField
                label="Таймаут підключення (мс)"
                value={settings.connection.connectionTimeout}
                onChange={(value) => updateSettings('connection', { connectionTimeout: value })}
                type="number"
                min={1000}
                max={30000}
              />
              <InputField
                label="Інтервал перепідключення (мс)"
                value={settings.connection.reconnectInterval}
                onChange={(value) => updateSettings('connection', { reconnectInterval: value })}
                type="number"
                min={1000}
                max={60000}
              />
              <InputField
                label="Максимум спроб перепідключення"
                value={settings.connection.maxReconnectAttempts}
                onChange={(value) => updateSettings('connection', { maxReconnectAttempts: value })}
                type="number"
                min={1}
                max={20}
              />
            </div>
            <div className="mt-4 pt-4 border-t border-secondary-100">
              <button
                onClick={() => handleReset('connection')}
                className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded hover:bg-red-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
              >
                Скинути розділ
              </button>
            </div>
          </SettingsSection>
        </div>

        {/* UI Settings */}
        <div className="animate-slideInFromLeft" style={{animationDelay: '0.2s'}}>
          <SettingsSection
            title="🎨 Налаштування інтерфейсу"
            isOpen={openSections.ui}
            onToggle={() => toggleSection('ui')}
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
              <SelectField
                label="Тема"
                value={settings.ui.theme}
                onChange={(value) => updateSettings('ui', { theme: value })}
                options={[
                  { value: 'light', label: 'Світла' },
                  { value: 'dark', label: 'Темна' },
                  { value: 'system', label: 'Системна' },
                ]}
              />
              <SelectField
                label="Мова"
                value={settings.ui.language}
                onChange={(value) => updateSettings('ui', { language: value })}
                options={[
                  { value: 'uk', label: 'Українська' },
                  { value: 'en', label: 'English' },
                ]}
              />
              <InputField
                label="Інтервал оновлення (мс)"
                value={settings.ui.refreshInterval}
                onChange={(value) => updateSettings('ui', { refreshInterval: value })}
                type="number"
                min={1000}
                max={60000}
              />
              <SelectField
                label="Формат дати"
                value={settings.ui.dateFormat}
                onChange={(value) => updateSettings('ui', { dateFormat: value })}
                options={[
                  { value: 'dd/mm/yyyy', label: 'ДД/ММ/РРРР' },
                  { value: 'mm/dd/yyyy', label: 'ММ/ДД/РРРР' },
                  { value: 'yyyy-mm-dd', label: 'РРРР-ММ-ДД' },
                ]}
              />
              <SelectField
                label="Формат часу"
                value={settings.ui.timeFormat}
                onChange={(value) => updateSettings('ui', { timeFormat: value })}
                options={[
                  { value: '24h', label: '24-годинний' },
                  { value: '12h', label: '12-годинний' },
                ]}
              />
            </div>
            <div className="mt-4">
              <ToggleField
                label="Компактний режим"
                description="Зменшує відступи і розміри елементів"
                checked={settings.ui.compactMode}
                onChange={(checked) => updateSettings('ui', { compactMode: checked })}
              />
            </div>
            <div className="mt-4 pt-4 border-t border-secondary-100">
              <button
                onClick={() => handleReset('ui')}
                className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded hover:bg-red-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
              >
                Скинути розділ
              </button>
            </div>
          </SettingsSection>
        </div>

        {/* Monitoring Settings */}
        <div className="animate-slideInFromRight" style={{animationDelay: '0.3s'}}>
          <SettingsSection
            title="📊 Налаштування моніторингу"
            isOpen={openSections.monitoring}
            onToggle={() => toggleSection('monitoring')}
          >
            <div className="mt-4">
              <h4 className="text-md font-medium text-secondary-800 mb-3 flex items-center">
                <div className="w-2 h-2 bg-blue-500 rounded-full mr-2 animate-pulse"></div>
                Сповіщення
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <ToggleField
                  label="Увімкнути сповіщення"
                  checked={settings.monitoring.enableNotifications}
                  onChange={(checked) => updateSettings('monitoring', { enableNotifications: checked })}
                />
                <ToggleField
                  label="Сповіщати про помилки"
                  checked={settings.monitoring.notifyOnErrors}
                  onChange={(checked) => updateSettings('monitoring', { notifyOnErrors: checked })}
                />
                <ToggleField
                  label="Сповіщати про нових клієнтів"
                  checked={settings.monitoring.notifyOnNewClients}
                  onChange={(checked) => updateSettings('monitoring', { notifyOnNewClients: checked })}
                />
                <ToggleField
                  label="Сповіщати про відключення"
                  checked={settings.monitoring.notifyOnDisconnects}
                  onChange={(checked) => updateSettings('monitoring', { notifyOnDisconnects: checked })}
                />
              </div>
            </div>

            <div className="mt-6">
              <h4 className="text-md font-medium text-secondary-800 mb-3 flex items-center">
                <div className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></div>
                Логування
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <SelectField
                  label="Рівень логування"
                  value={settings.monitoring.logLevel}
                  onChange={(value) => updateSettings('monitoring', { logLevel: value })}
                  options={[
                    { value: 'debug', label: 'Debug' },
                    { value: 'info', label: 'Info' },
                    { value: 'warn', label: 'Warning' },
                    { value: 'error', label: 'Error' },
                  ]}
                />
                <InputField
                  label="Максимум записів логу"
                  value={settings.monitoring.maxLogEntries}
                  onChange={(value) => updateSettings('monitoring', { maxLogEntries: value })}
                  type="number"
                  min={100}
                  max={10000}
                />
              </div>
            </div>

            <div className="mt-6">
              <h4 className="text-md font-medium text-secondary-800 mb-3 flex items-center">
                <div className="w-2 h-2 bg-purple-500 rounded-full mr-2 animate-pulse"></div>
                Метрики
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <ToggleField
                  label="Увімкнути метрики"
                  checked={settings.monitoring.enableMetrics}
                  onChange={(checked) => updateSettings('monitoring', { enableMetrics: checked })}
                />
                <InputField
                  label="Інтервал метрик (мс)"
                  value={settings.monitoring.metricsInterval}
                  onChange={(value) => updateSettings('monitoring', { metricsInterval: value })}
                  type="number"
                  min={500}
                  max={10000}
                />
                <ToggleField
                  label="Показувати використання CPU"
                  checked={settings.monitoring.showCpuUsage}
                  onChange={(checked) => updateSettings('monitoring', { showCpuUsage: checked })}
                />
                <ToggleField
                  label="Показувати використання пам'яті"
                  checked={settings.monitoring.showMemoryUsage}
                  onChange={(checked) => updateSettings('monitoring', { showMemoryUsage: checked })}
                />
                <ToggleField
                  label="Показувати мережеву активність"
                  checked={settings.monitoring.showNetworkUsage}
                  onChange={(checked) => updateSettings('monitoring', { showNetworkUsage: checked })}
                />
              </div>
            </div>
            <div className="mt-4 pt-4 border-t border-secondary-100">
              <button
                onClick={() => handleReset('monitoring')}
                className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded hover:bg-red-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
              >
                Скинути розділ
              </button>
            </div>
          </SettingsSection>
        </div>

        {/* Security Settings */}
        <div className="animate-slideInFromLeft" style={{animationDelay: '0.4s'}}>
          <SettingsSection
            title="🔒 Налаштування безпеки"
            isOpen={openSections.security}
            onToggle={() => toggleSection('security')}
          >
            <div className="mt-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <ToggleField
                  label="Увімкнути автентифікацію"
                  description="Вимагати логін для доступу"
                  checked={settings.security.enableAuth}
                  onChange={(checked) => updateSettings('security', { enableAuth: checked })}
                />
                <InputField
                  label="Таймаут сесії (секунди)"
                  value={settings.security.sessionTimeout}
                  onChange={(value) => updateSettings('security', { sessionTimeout: value })}
                  type="number"
                  min={300}
                  max={86400}
                />
                <ToggleField
                  label="Двофакторна автентифікація"
                  description="Додатковий рівень безпеки"
                  checked={settings.security.requireTwoFactor}
                  onChange={(checked) => updateSettings('security', { requireTwoFactor: checked })}
                />
                <ToggleField
                  label="Аудит лог"
                  description="Логування дій користувачів"
                  checked={settings.security.enableAuditLog}
                  onChange={(checked) => updateSettings('security', { enableAuditLog: checked })}
                />
              </div>
            </div>

            <div className="mt-6">
              <h4 className="text-md font-medium text-secondary-800 mb-3 flex items-center">
                <div className="w-2 h-2 bg-red-500 rounded-full mr-2 animate-pulse"></div>
                Політика паролів
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <InputField
                  label="Мінімальна довжина"
                  value={settings.security.passwordPolicy.minLength}
                  onChange={(value) => updateSettings('security', { 
                    passwordPolicy: { ...settings.security.passwordPolicy, minLength: value }
                  })}
                  type="number"
                  min={4}
                  max={50}
                />
                <div className="space-y-2">
                  <ToggleField
                    label="Великі літери"
                    checked={settings.security.passwordPolicy.requireUppercase}
                    onChange={(checked) => updateSettings('security', { 
                      passwordPolicy: { ...settings.security.passwordPolicy, requireUppercase: checked }
                    })}
                  />
                  <ToggleField
                    label="Цифри"
                    checked={settings.security.passwordPolicy.requireNumbers}
                    onChange={(checked) => updateSettings('security', { 
                      passwordPolicy: { ...settings.security.passwordPolicy, requireNumbers: checked }
                    })}
                  />
                  <ToggleField
                    label="Спеціальні символи"
                    checked={settings.security.passwordPolicy.requireSymbols}
                    onChange={(checked) => updateSettings('security', { 
                      passwordPolicy: { ...settings.security.passwordPolicy, requireSymbols: checked }
                    })}
                  />
                </div>
              </div>
            </div>

            <div className="mt-6">
              <h4 className="text-md font-medium text-secondary-800 mb-3 flex items-center">
                <div className="w-2 h-2 bg-orange-500 rounded-full mr-2 animate-pulse"></div>
                Дозволені IP адреси
              </h4>
              <div className="space-y-2">
                {settings.security.allowedIPs.map((ip, index) => (
                  <div key={index} className="flex items-center gap-2 transform transition-all duration-300 hover:translate-x-2">
                    <input
                      type="text"
                      value={ip}
                      onChange={(e) => {
                        const newIPs = [...settings.security.allowedIPs];
                        newIPs[index] = e.target.value;
                        updateSettings('security', { allowedIPs: newIPs });
                      }}
                      className="flex-1 px-3 py-2 border border-secondary-300 rounded-md focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all duration-300 hover:border-primary-300 focus:scale-[1.02]"
                    />
                    <button
                      onClick={() => {
                        const newIPs = settings.security.allowedIPs.filter((_, i) => i !== index);
                        updateSettings('security', { allowedIPs: newIPs });
                      }}
                      className="px-3 py-2 bg-red-100 text-red-700 rounded hover:bg-red-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
                    >
                      Видалити
                    </button>
                  </div>
                ))}
                <button
                  onClick={() => {
                    const newIPs = [...settings.security.allowedIPs, ''];
                    updateSettings('security', { allowedIPs: newIPs });
                  }}
                  className="px-3 py-2 bg-green-100 text-green-700 rounded hover:bg-green-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
                >
                  Додати IP
                </button>
              </div>
            </div>
            <div className="mt-4 pt-4 border-t border-secondary-100">
              <button
                onClick={() => handleReset('security')}
                className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded hover:bg-red-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
              >
                Скинути розділ
              </button>
            </div>
          </SettingsSection>
        </div>

        {/* Export Settings */}
        <div className="animate-slideInFromRight" style={{animationDelay: '0.5s'}}>
          <SettingsSection
            title="📤 Налаштування експорту"
            isOpen={openSections.export}
            onToggle={() => toggleSection('export')}
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
              <ToggleField
                label="Автоматичний експорт логів"
                description="Регулярний експорт даних"
                checked={settings.export.autoExportLogs}
                onChange={(checked) => updateSettings('export', { autoExportLogs: checked })}
              />
              <SelectField
                label="Формат експорту"
                value={settings.export.exportFormat}
                onChange={(value) => updateSettings('export', { exportFormat: value })}
                options={[
                  { value: 'json', label: 'JSON' },
                  { value: 'csv', label: 'CSV' },
                  { value: 'xml', label: 'XML' },
                ]}
              />
              <SelectField
                label="Інтервал експорту"
                value={settings.export.exportInterval}
                onChange={(value) => updateSettings('export', { exportInterval: value })}
                options={[
                  { value: 'daily', label: 'Щодня' },
                  { value: 'weekly', label: 'Щотижня' },
                  { value: 'monthly', label: 'Щомісяця' },
                ]}
              />
              <InputField
                label="Максимальний розмір (MB)"
                value={settings.export.maxExportSize}
                onChange={(value) => updateSettings('export', { maxExportSize: value })}
                type="number"
                min={1}
                max={1000}
              />
            </div>

            <div className="mt-6">
              <h4 className="text-md font-medium text-secondary-800 mb-3 flex items-center">
                <div className="w-2 h-2 bg-indigo-500 rounded-full mr-2 animate-pulse"></div>
                Що включати в експорт
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <ToggleField
                  label="Метрики"
                  checked={settings.export.includeMetrics}
                  onChange={(checked) => updateSettings('export', { includeMetrics: checked })}
                />
                <ToggleField
                  label="Логи"
                  checked={settings.export.includeLogs}
                  onChange={(checked) => updateSettings('export', { includeLogs: checked })}
                />
                <ToggleField
                  label="Дані клієнтів"
                  checked={settings.export.includeClientData}
                  onChange={(checked) => updateSettings('export', { includeClientData: checked })}
                />
              </div>
            </div>
            <div className="mt-4 pt-4 border-t border-secondary-100">
              <button
                onClick={() => handleReset('export')}
                className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded hover:bg-red-200 transition-all duration-300 transform hover:scale-105 active:scale-95"
              >
                Скинути розділ
              </button>
            </div>
          </SettingsSection>
        </div>
      </div>
    </div>
  );
};
